import limited_client as robot, numpy as np

def read():
 s=robot.observe(2)['robot'];return np.array(s['joint_positions']),np.array(s['tcp_position']),np.array(s['tcp_quaternion_wxyz'])
def qlog(q):
 q=np.array(q,float);q/=np.linalg.norm(q)
 if q[0]<0:q=-q
 n=np.linalg.norm(q[1:]);a=2*np.arctan2(n,q[0]);return np.zeros(3) if n<1e-9 else q[1:]/n*a
def qmul(a,b):
 w,x,y,z=a;W,X,Y,Z=b
 return np.array([w*W-x*X-y*Y-z*Z,w*X+x*W+y*Z-z*Y,w*Y-x*Z+y*W+z*X,w*Z+x*Y-y*X+z*W])
def rel(a,b):return qlog(qmul(np.r_[a[0],-a[1:]],b))
def cmd(q,n):
 for _ in range(n):robot.step(list(q)+[.04,.04])
q0,p0,o0=read();cmd(q0,5);q0,p0,o0=read();J=np.zeros((6,7))
for j in range(7):
 states=[]
 for sign in (+1,-1):
  t=q0.copy();t[j]+=.06*sign;cmd(t,2);states.append(read());cmd(q0,5)
 (qp,pp,op),(qm,pm,om)=states;dq=qp[j]-qm[j]
 if abs(dq)<.005:print('skip',j,dq);continue
 J[:3,j]=(pp-pm)/dq;J[3:,j]=rel(om,op)/dq
 print(j,'dq',dq,'dp',pp-pm)
np.save('/app/output/jacobian_local.npy',J);print('base',q0,p0,o0);print(J)
PY
